--
-- Table structure for table `packages`
--

DROP TABLE IF EXISTS `packages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `packages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `package_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tracking_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hfl_package_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int NOT NULL DEFAULT '0',
  `shipping_mode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pricing_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GC',
  `from_warehouse` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_warehouse` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `boxes` json DEFAULT NULL,
  `total_cbm` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `total_weight` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `box_count` int NOT NULL DEFAULT '0',
  `pricing_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pricing_rate_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_rate` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `shipping_cost` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `delivery_fee` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `handling_fee` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `warehouse_fee` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `other_fee` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `discount` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `grand_total` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `warehouse_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_driver_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `received_at` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_received_at` datetime DEFAULT NULL,
  `received_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `received_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `received_relation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_remark` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `china_waybill_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `china_container_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_images` json DEFAULT NULL,
  `custom_images` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `packages_hfl_package_code_unique` (`hfl_package_code`),
  KEY `packages_customer_id_tracking_number_status_index` (`customer_id`,`tracking_number`,`status`),
  KEY `packages_pricing_type_index` (`pricing_type`),
  KEY `packages_china_waybill_number_index` (`china_waybill_number`),
  KEY `packages_china_container_number_index` (`china_container_number`),
  KEY `packages_hfl_package_code_index` (`hfl_package_code`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

